"""Search for a correct clause gadget: 3 input nodes (colored T=0/F=1),
a fixed base node B (color 2), and some aux nodes, such that the graph is
3-colorable (extending the input coloring) iff at least one input is T=0.
Inputs must not be adjacent to each other (they are shared across clauses).
"""
import itertools, sys

def colorable(n, adj, fixed):
    # fixed: dict node->color
    col = [-1]*n
    for k,v in fixed.items():
        col[k]=v
    order = [i for i in range(n) if i not in fixed]
    def bt(idx):
        if idx==len(order): return True
        u=order[idx]
        used={col[v] for v in adj[u] if col[v]!=-1}
        for c in range(3):
            if c not in used:
                col[u]=c
                if bt(idx+1): return True
                col[u]=-1
        return False
    return bt(0)

def check(n, edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # inputs 0,1,2 ; B = 3 fixed color 2
    for c in itertools.product((0,1),repeat=3):
        fixed={0:c[0],1:c[1],2:c[2],3:2}
        col_ok = colorable(n, adj, fixed)
        want = (c[0]==0 or c[1]==0 or c[2]==0)
        if col_ok != want:
            return False
    return True

def search(num_aux, max_results=3):
    inputs=[0,1,2]; B=3
    aux=list(range(4,4+num_aux))
    nodes=inputs+[B]+aux
    # candidate edges: all pairs except input-input, and except involving B? allow B edges.
    cand=[]
    for i in range(len(nodes)):
        for j in range(i+1,len(nodes)):
            u,v=nodes[i],nodes[j]
            if u in inputs and v in inputs: continue
            cand.append((u,v))
    n=4+num_aux
    found=[]
    # brute force over subsets (limit)
    total=1<<len(cand)
    if total> 1<<24:
        print("too many", total); return found
    for mask in range(total):
        edges=[cand[i] for i in range(len(cand)) if mask>>i & 1]
        if check(n, edges):
            found.append(edges)
            if len(found)>=max_results: break
    return found

if __name__=="__main__":
    for a in range(0,4):
        print("aux",a, "searching...", flush=True)
        f=search(a)
        print("  found",len(f))
        for e in f[:2]:
            print("   ", e)
        if f: break
