import random, time
from reduce import reduce

def coloring_solver(instance):
    n = instance["n"]
    adj = [set() for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u].add(v); adj[v].add(u)
    dom = [ {0,1,2} for _ in range(n) ]
    assign = [-1]*n

    def propagate():
        # returns False on contradiction
        stack = [i for i in range(n) if len(dom[i])==1 and assign[i]==-1]
        while stack:
            v = stack.pop()
            if assign[v] != -1:
                continue
            c = next(iter(dom[v]))
            assign[v] = c
            for u in adj[v]:
                if assign[u] == c:
                    return False
                if c in dom[u]:
                    dom[u].discard(c)
                    if not dom[u]:
                        return False
                    if len(dom[u])==1 and assign[u]==-1:
                        stack.append(u)
        return True

    def bt():
        if not propagate():
            return False
        # choose unassigned with smallest domain, max degree
        best=-1; bestkey=None
        for v in range(n):
            if assign[v]==-1:
                key=(len(dom[v]), -len(adj[v]))
                if bestkey is None or key<bestkey:
                    bestkey=key; best=v
        if best==-1:
            return True
        v=best
        saved_dom=[set(d) for d in dom]
        saved_asg=list(assign)
        for c in list(dom[v]):
            dom[v]={c}
            if bt():
                return True
            for i in range(n):
                dom[i]=set(saved_dom[i])
            assign[:] = saved_asg
        return False

    return bt()

rng = random.Random(1)
def random_sat(m,k):
    cl=[]
    for _ in range(k):
        vs=rng.sample(range(1,m+1),3)
        cl.append([v if rng.random()<0.5 else -v for v in vs])
    return {"num_vars":m,"clauses":cl}

for (m,k) in [(3,8),(4,12),(5,12),(5,20)]:
    t=time.time(); worst=0
    for _ in range(100):
        g=reduce(random_sat(m,k))
        t0=time.time(); coloring_solver(g); worst=max(worst,time.time()-t0)
    print(m,k,"100 solves",round(time.time()-t,3),"worst",round(worst,4))
PY"}

