import random, sys
sys.setrecursionlimit(1000000)

def solve_cnf(clauses, nv):
    """Correct DPLL with unit propagation. clauses: list of lists of ints."""
    def rec(cls):
        cls = [list(c) for c in cls]
        # unit propagation
        changed = True
        while changed:
            changed = False
            units = [c[0] for c in cls if len(c) == 1]
            if any(len(c) == 0 for c in cls):
                return False
            if not units:
                break
            for lit in units:
                new = []
                for c in cls:
                    if lit in c:
                        continue
                    if -lit in c:
                        c2 = [x for x in c if x != -lit]
                        if not c2:
                            return False
                        new.append(c2)
                    else:
                        new.append(c)
                cls = new
                changed = True
                if not cls:
                    return True
        if not cls:
            return True
        sc = min(cls, key=len)
        lit = sc[0]
        for choice in (lit, -lit):
            if rec(cls + [[choice]]):
                return True
        return False
    return rec(clauses)

def dpll_color(instance):
    n = instance["n"]
    if n == 0: return True
    clauses = []
    for v in range(n):
        clauses.append([v*3+0, v*3+1, v*3+2])
        clauses.append([-(v*3+0), -(v*3+1)])
        clauses.append([-(v*3+0), -(v*3+2)])
        clauses.append([-(v*3+1), -(v*3+2)])
    for u, w in instance["edges"]:
        for c in range(3):
            clauses.append([-(u*3+c), -(w*3+c)])
    return solve_cnf(clauses, n*3)

def naive_color(instance):
    n=instance["n"]
    adj=[set() for _ in range(n)]
    for u,v in instance["edges"]:
