        sc = min(cls, key=len)
        lit = sc[0]
        for choice in (lit, -lit):
            if rec(cls + [[choice]]):
                return True
        return False
    return rec(clauses)

def dpll_color(instance):
    n = instance["n"]
    if n == 0: return True
    clauses = []
    for v in range(n):
        clauses.append([v*3+0, v*3+1, v*3+2])
        clauses.append([-(v*3+0), -(v*3+1)])
        clauses.append([-(v*3+0), -(v*3+2)])
        clauses.append([-(v*3+1), -(v*3+2)])
    for u, w in instance["edges"]:
        for c in range(3):
            clauses.append([-(u*3+c), -(w*3+c)])
    return solve_cnf(clauses, n*3)

def naive_color(instance):
    n=instance["n"]
    adj=[set() for _ in range(n)]
    for u,v in instance["edges"]:
